// Receipt rendering for the point-of-sale printer.

import { formatMoney } from "./money.ts";

export interface ReceiptItem {
  name: string;
  cents: number;
}

export function renderReceipt(items: ReceiptItem[]): string {
  const rows = items.map((i) => `${i.name.padEnd(16)}${formatMoney(i.cents).padStart(10)}`);
  const total = items.reduce((sum, i) => sum + i.cents, 0);
  rows.push("-".repeat(26));
  rows.push(`${"Total".padEnd(16)}${formatMoney(total).padStart(10)}`);
  return rows.join("\n");
}
// Invoice rendering for the customer portal.

import { formatMoney } from "./money.ts";

export interface Line {
  description: string;
  cents: number;
}

export function renderInvoice(lines: Line[]): string {
  const rows = lines.map((l) => `${l.description.padEnd(20)} ${formatMoney(l.cents).padStart(12)}`);
  const total = lines.reduce((sum, l) => sum + l.cents, 0);
  rows.push(`${"TOTAL".padEnd(20)} ${formatMoney(total).padStart(12)}`);
  return rows.join("\n");
}
